pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to avoid overflow but keep domain wide enough to include bug triggers
        vm.assume(amount > 0 && amount <= address(this).balance);
        // Deploy a helper that records if it received value
        TargetTracker tracker = new TargetTracker();
        // Fund the test contract
        vm.deal(address(this), amount);
        // Set the target to the tracker so we can observe where the call goes
        // We need to set the target defined in C. Since C hardcodes the target, we can't change it.
        // Instead, we observe the external call destination by checking the balance of the original target.
        // Original target is hardcoded: 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C
        address originalTarget = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        uint256 balanceBefore = originalTarget.balance;
        // Call go() with value
        c.go{value: amount}();
        uint256 balanceAfter = originalTarget.balance;
        // Assert: the original target's balance increased by exactly the amount sent,
        // meaning the external call went to the correct address
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
contract TargetTracker {
    event Received(address sender, uint256 value);
    fallback() external payable {
        emit Received(msg.sender, msg.value);
    }
